package com.chektek;

import com.chektek.payload.*;
import net.runelite.api.Client;
import net.runelite.api.HeadIcon;

import java.util.Objects;

public class PayloadCache {

	private static PayloadCache instance = new PayloadCache();

	public ActivityPayload activityPayload = new ActivityPayload();
	public FPSPayload fpsPayload = new FPSPayload();
	public EquipmentPayload equipmentPayload = new EquipmentPayload();
	public GrandExchangePayload grandExchangePayload = new GrandExchangePayload();
	public OverheadPayload overheadPayload = new OverheadPayload();
	public PVPPayload pvpPayload = new PVPPayload();
	public SkillsPayload skillsPayload = new SkillsPayload();
	public MovementPayload movementPayload = new MovementPayload();

	public static PayloadCache getInstance() {
		return instance;
	}

	public void clearCache() {
		activityPayload = new ActivityPayload();
		fpsPayload = new FPSPayload();
		equipmentPayload = new EquipmentPayload();
		grandExchangePayload = new GrandExchangePayload();
		overheadPayload = new OverheadPayload();
		pvpPayload = new PVPPayload();
		skillsPayload = new SkillsPayload();
		movementPayload = new MovementPayload();

	}

	public boolean isNewOverheadPayloadRequired(Client client) {
		if (overheadPayload == null) {
			return true;
		} else {
			HeadIcon overheadIcon = client.getLocalPlayer().getOverheadIcon();
			if (overheadIcon == null) {
				return false;
			}

			return !Objects.equals(overheadPayload.getOverheadIcon(), overheadIcon.name());
		}
	}
}

package com.chektek;

import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

import javax.inject.Inject;
import javax.swing.SwingUtilities;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;

public class PluginControlService {

	private static final Logger LOGGER = LoggerFactory.getLogger(PluginControlService.class);

	private final PluginManager pluginManager;

	@Inject
	public PluginControlService(PluginManager pluginManager) {
		this.pluginManager = pluginManager;
	}

	public List<PluginSummary> getPluginSummaries() {
		return pluginManager.getPlugins().stream()
				.map(plugin -> new PluginSummary(
						getPluginId(plugin),
						getPluginName(plugin),
						pluginManager.isPluginActive(plugin)))
				.sorted(Comparator.comparing(PluginSummary::getName,
						String.CASE_INSENSITIVE_ORDER))
				.collect(Collectors.toList());
	}

	public PluginSummary getPluginSummary(Plugin plugin, boolean isActive) {
		if (plugin == null) {
			return null;
		}

		return new PluginSummary(
				getPluginId(plugin),
				getPluginName(plugin),
				isActive);
	}

	public void togglePlugin(String pluginId, Boolean isActive) {
		if (isActive == null) {
			LOGGER.warn("togglePlugin request missing isActive for plugin: " + pluginId);
			return;
		}

		Plugin plugin = pluginManager.getPlugins().stream()
				.filter(candidate -> getPluginId(candidate).equals(pluginId))
				.findFirst()
				.orElse(null);

		if (plugin == null) {
			LOGGER.warn("Could not find plugin with id: " + pluginId);
			return;
		}

		try {
			if (isActive) {
				if (!pluginManager.isPluginEnabled(plugin)) {
					pluginManager.setPluginEnabled(plugin, true);
				}

				if (!pluginManager.isPluginActive(plugin)) {
					SwingUtilities.invokeLater(() -> {
						try {
							pluginManager.startPlugin(plugin);
						} catch (Exception ex) {
							LOGGER.warn("Failed to start plugin: " + plugin.getName(), ex);
						}
					});
				}
			} else {
				if (pluginManager.isPluginActive(plugin)) {
					SwingUtilities.invokeLater(() -> {
						try {
							pluginManager.stopPlugin(plugin);
						} catch (Exception ex) {
							LOGGER.warn("Failed to start plugin: " + plugin.getName(), ex);
						}
					});
				}

				if (pluginManager.isPluginEnabled(plugin)) {
					pluginManager.setPluginEnabled(plugin, false);
				}
			}
		} catch (Throwable e) {
			LOGGER.warn("Failed to toggle plugin {} to isActive={}", pluginId, isActive, e);
		}
	}

	private String getPluginId(Plugin plugin) {
		String canonicalName = plugin.getClass().getCanonicalName();
		if (canonicalName != null) {
			return canonicalName;
		}
		return plugin.getClass().getName();
	}

	private String getPluginName(Plugin plugin) {
		PluginDescriptor descriptor = plugin.getClass().getAnnotation(PluginDescriptor.class);
		if (descriptor != null && descriptor.name() != null && !descriptor.name().isEmpty()) {
			return descriptor.name();
		}
		return plugin.getClass().getSimpleName();
	}
}

