import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(name = "Rune Deck", description = "A data connector for the Rune Deck.", enabledByDefault = true)
public class RuneDeckPlugin extends Plugin {

	private static final Logger LOGGER = LoggerFactory.getLogger(RuneDeckConfig.class);
	private static final int[] PORTS_TO_TRY = { 42023, 43060, 43020 };
	private PayloadCache payloadCache = PayloadCache.getInstance();

	@Inject
	private Client client;

	@Inject
	private Gson gson;

	@Inject
	private PluginControlService pluginControlService;

	private RuneDeckSocketServer runeDeckSocketServer;

	static boolean isPortAvailable(int port) {
		try (ServerSocket serverSocket = new ServerSocket()) {
			serverSocket.setReuseAddress(true);
			serverSocket.bind(new InetSocketAddress("127.0.0.1", port));
			return true;
		} catch (Exception e) {
			return false;
		}
	}

	@Override
	protected void startUp() throws Exception {
		Exception lastException = null;

		for (int port : PORTS_TO_TRY) {
			if (!isPortAvailable(port)) {
				LOGGER.info("Port " + port + " is already in use; trying next");
				continue;
			}

			try {
				this.runeDeckSocketServer = new RuneDeckSocketServer(port, gson, pluginControlService);
				this.runeDeckSocketServer.start();
				LOGGER.info("RuneDeckSocketServer starting on port: " + port);
				return;
			} catch (Exception e) {
				LOGGER.warn("Failed to start server on port " + port + ": " + e.getMessage());
				lastException = e;
				this.runeDeckSocketServer = null;
			}
		}

		throw new Exception("Failed to start RuneDeckSocketServer on any port", lastException);
	}

	@Override
	protected void shutDown() throws Exception {
		if (this.runeDeckSocketServer != null) {
			this.runeDeckSocketServer.stop();
			this.runeDeckSocketServer = null;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged) {

		GameState gameState = gameStateChanged.getGameState();

		boolean userLoggedIn = gameState == GameState.LOGGED_IN;
		boolean gameIsLoading = gameState == GameState.LOADING;

		if (userLoggedIn || gameIsLoading)
			return;

		this.runeDeckSocketServer.broadcast(new LogoutPayload());
		payloadCache.clearCache();
	}

	@Subscribe
	public void onGameTick(GameTick tick) {

		if (payloadCache.movementPayload.isNewPayload(this.client)) {
			payloadCache.movementPayload = new MovementPayload(this.client);
			this.runeDeckSocketServer.broadcast(payloadCache.movementPayload);
		}

		if (payloadCache.overheadPayload.isNewPayload(this.client)) {
			payloadCache.overheadPayload = new OverheadPayload(this.client);
			this.runeDeckSocketServer.broadcast(payloadCache.overheadPayload);
		}

		if (payloadCache.skillsPayload.isNewPayload(this.client)) {
			payloadCache.skillsPayload = new SkillsPayload(this.client);
			this.runeDeckSocketServer.broadcast(payloadCache.skillsPayload);
		}

		if (payloadCache.pvpPayload.isNewPayload(this.client)) {
			payloadCache.pvpPayload = new PVPPayload(this.client);
			this.runeDeckSocketServer.broadcast(payloadCache.pvpPayload);
		}

		if (payloadCache.equipmentPayload.isNewPayload(this.client)) {
			payloadCache.equipmentPayload = new EquipmentPayload(this.client);
			this.runeDeckSocketServer.broadcast(payloadCache.equipmentPayload);
		}

		if (payloadCache.fpsPayload.isNewPayload(this.client)) {
			payloadCache.fpsPayload = new FPSPayload(this.client);
			this.runeDeckSocketServer.broadcast(payloadCache.fpsPayload);
		}

		if (payloadCache.grandExchangePayload.isNewPayload(this.client)) {
			payloadCache.grandExchangePayload = new GrandExchangePayload(this.client);
			this.runeDeckSocketServer.broadcast(payloadCache.grandExchangePayload);
		}

		if (payloadCache.activityPayload.isNewPayload(this.client)) {
			payloadCache.activityPayload = new ActivityPayload(this.client);
			this.runeDeckSocketServer.broadcast(payloadCache.activityPayload);
		}

	}

	@Subscribe
	public void onPluginChanged(PluginChanged pluginChanged) {
		if (this.runeDeckSocketServer == null) {
			return;
		}

		this.runeDeckSocketServer.broadcastPluginChange(pluginChanged.getPlugin(), pluginChanged.isLoaded());
	}

	@Provides
	RuneDeckConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(RuneDeckConfig.class);
	}
}

package com.chektek;

import java.util.List;
import java.util.Map;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.chektek.payload.Payload;
import com.chektek.payload.PayloadType;
import com.chektek.websocket.WebSocketConnection;
import com.chektek.websocket.WebSocketServer;
import com.google.gson.Gson;

import net.runelite.client.plugins.Plugin;

public class RuneDeckSocketServer extends WebSocketServer {

	private static final Logger LOGGER = LoggerFactory.getLogger(RuneDeckSocketServer.class);

	private final Gson gson;
	private final PluginControlService pluginControlService;

	private PayloadCache payloadCache = PayloadCache.getInstance();

	public RuneDeckSocketServer(int port, Gson gson, PluginControlService pluginControlService) {
		super(port);
		this.gson = gson;
		this.pluginControlService = pluginControlService;
	}

	public void broadcast(Payload payload) {
		String payloadJSON = this.gson.toJson(payload);
		super.broadcast(payloadJSON);
	}

	@Override
	public void onOpen(WebSocketConnection conn) {
		try {
			LOGGER.info("Client connected: " + conn.getRemoteAddress());
		} catch (Exception e) {
			LOGGER.info("Client connected");
		}
		payloadCache.clearCache();
	}

	@Override
	public void onClose(WebSocketConnection conn) {
		payloadCache.clearCache();
		LOGGER.info("RuneDeckSocketServer closed connection");
	}

	@Override
	public void onMessage(WebSocketConnection conn, String messageString) {
		String messageType = null;
		try {
			Message message = this.gson.fromJson(messageString, Message.class);

			if (message == null || message.messageType == null) {
				return;
			}

			messageType = message.messageType;

			if (message.messageType.equals("clearCache")) {
				payloadCache.clearCache();
			}

			if (message.messageType.equals("getPlugins")) {
				broadcastPluginList();
			}

			if (message.messageType.equals("togglePlugin")) {
				if (message.pluginId != null && message.isActive != null) {
					pluginControlService.togglePlugin(message.pluginId, message.isActive);
				} else {
					LOGGER.warn("togglePlugin request missing pluginId or isActive");
				}
			}

		} catch (Exception e) {
			LOGGER.warn("Failed to handle websocket message. rawMessage={}, messageType={}", messageString, messageType, e);
		}
	}

	public void broadcastPluginList() {
		List<PluginSummary> plugins = pluginControlService.getPluginSummaries();
		broadcast(this.gson.toJson(Map.of("type", PayloadType.PLUGINS, "plugins", plugins)));
	}

	public void broadcastPluginChange(Plugin plugin, boolean isActive) {
		PluginSummary pluginSummary = pluginControlService.getPluginSummary(plugin, isActive);
		if (pluginSummary == null) {
			return;
		}

		broadcast(this.gson.toJson(Map.of("type", PayloadType.PLUGIN_CHANGED, "plugin", pluginSummary)));
	}

	@Override
	public void onError(WebSocketConnection conn, Exception ex) {
		payloadCache.clearCache();
		LOGGER.error(ex.getMessage());
	}

	@Override
	public void onStart() {
		payloadCache.clearCache();
		LOGGER.info("RuneDeckSocketServer started on port: " + this.getPort());
	}
}

package com.chektek.payload;

import com.chektek.AnimationCollections;

import net.runelite.api.Client;
import net.runelite.api.Player;

public class ActivityPayload extends Payload {
	private boolean isActive;
	private static final int INACTIVE_DEBOUNCE_TICKS = 3;
	private transient int inactiveStreakTicks = 0;

	public ActivityPayload() {
		super(PayloadType.ACTIVITY);
	}

	public ActivityPayload(Client client) {
		super(PayloadType.ACTIVITY);

		this.isActive = isCurrentlyActive(client);
	}

	public boolean isActive() {
		return isActive;
	}

	private static boolean isCurrentlyActive(Client client) {
		Player player = client.getLocalPlayer();
		if (player == null) {
			return false; // Safety check
		}

		int animation = player.getAnimation();
		boolean isFishing = AnimationCollections.isFishingAnimation(animation);

		// Player is performing a non-idle animation
		if (animation != -1) {
			// For fishing, only count as active if still targeting the fishing spot
			if (isFishing) {
				return player.getInteracting() != null;
			}
			return true; // Any other animation = active
		}

		// Player is targeting/interacting with another actor
		if (player.isInteracting()) {
			return true;
		}

		// Player is moving (walking/running)
		if (player.getPoseAnimation() != player.getIdlePoseAnimation()) {
			return true;
		}

		return false;
	}

	@Override
	public boolean isNewPayload(Client client) {
		boolean activeNow = isCurrentlyActive(client);

		if (activeNow) {
			inactiveStreakTicks = 0;
			return !this.isActive; // became active -> report immediately
		}

		// inactive this tick
		inactiveStreakTicks++;

		// If we were active, require N consecutive inactive ticks before reporting
		// inactive.
		if (this.isActive && inactiveStreakTicks < INACTIVE_DEBOUNCE_TICKS) {
			return false;
		}

		return this.isActive; // became (debounced) inactive -> report
	}
}

package com.chektek.payload;

import net.runelite.api.Client;
import net.runelite.api.PlayerComposition;

import java.util.Arrays;

public class EquipmentPayload extends Payload {
    private int[] playerEquipmentIds;

    public EquipmentPayload() {
        super(PayloadType.EQUIPMENT);
    }

    public EquipmentPayload(Client client) {
        super(PayloadType.EQUIPMENT);

        PlayerComposition composition = client.getLocalPlayer().getPlayerComposition();
        this.playerEquipmentIds = composition != null ? composition.getEquipmentIds() : null;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        EquipmentPayload that = (EquipmentPayload) o;
        return Arrays.equals(playerEquipmentIds, that.playerEquipmentIds);
    }

    @Override
    public int hashCode() {
        return Arrays.hashCode(playerEquipmentIds);
    }

    public int[] getPlayerEquipmentIds() {
        return playerEquipmentIds;
    }

    @Override
    public boolean isNewPayload(Client client) {
        PlayerComposition composition = client.getLocalPlayer().getPlayerComposition();
        return composition == null ? this.getPlayerEquipmentIds() != null : !Arrays.equals(composition.getEquipmentIds(), this.getPlayerEquipmentIds());
    }
}

